+import { findUser, findUserByEmail, listRecentUsers } from "./db/queries.ts";
+import { recordAudit } from "./db/audit.ts";
+
+const example = async () => {
+  // ✓ This is type-safe — TypeScript knows findUser returns User | null
+  const user = await findUser("user-123");
+  if (user) {
+    console.log(user.id, user.email, user.createdAt);
+  }
+
+  // ✓ This is type-safe — TypeScript knows findUserByEmail returns User | null
+  const userByEmail = await findUserByEmail("test@example.com");
+  if (userByEmail) {
+    const userId = userByEmail.id;
+    console.log(userId);
+  }
+
+  // ✓ This is type-safe — TypeScript knows listRecentUsers returns User[]
+  const recentUsers = await listRecentUsers(10);
+  recentUsers.forEach((user) => {
+    console.log(`${user.email} created at ${user.createdAt}`);
+  });
+
+  // ✓ This is type-safe — audit recording is validated
+  await recordAudit("admin", "login");
+
+  // ✗ If you try to access a column that doesn't exist in schema, TypeScript catches it:
+  // @ts-expect-error: Property 'non_existent_column' does not exist on User
+  const broken = user?.non_existent_column;
+
+  // ✗ If a migration renamed created_at → created_on and schema wasn't updated,
+  // any query still using the old name fails at type-check time:
+  // @ts-expect-error: Property 'createdAt' does not exist (if schema was updated to 'created_on')
+  // const renamed = user?.createdAt;
+};
